## TASK B (Task 13): Success chime (interaction-gated, mute-aware)
Files: create `client/src/lib/sound.ts`, `client/src/lib/__tests__/sound.test.ts`, and a real audio asset.
====================================================================

### Step 0 — Generate a real chime audio asset as WAV (NOT mp3).
Create the directory `client/public/sounds/`. Write a short, pleasant two-note "success" chime as a 16-bit PCM mono WAV at `client/public/sounds/payment-success.wav` using a Node script you run once. The chime: ~0.45s total, two ascending sine tones (e.g. 880Hz then 1320Hz, ~0.18s each with a short gap), with a quick fade-out on each note to avoid clicks, amplitude ~0.3, 44100 Hz sample rate. Example approach (write and run a temporary node script, then delete the script — do NOT commit the script):

```js
// scripts/_gen_chime.cjs (temporary, delete after running)
const fs = require('fs');
const SR = 44100, notes = [{f:880,d:0.18},{f:0,d:0.04},{f:1320,d:0.22}];
let samples = [];
for (const n of notes) {
  const N = Math.floor(SR * n.d);
  for (let i = 0; i < N; i++) {
    const t = i / SR;
    const env = n.f === 0 ? 0 : Math.min(1, i/ (SR*0.01)) * Math.min(1, (N-i)/(SR*0.05)); // attack+release
    samples.push(n.f === 0 ? 0 : 0.3 * env * Math.sin(2*Math.PI*n.f*t));
  }
}
const buf = Buffer.alloc(44 + samples.length*2);
buf.write('RIFF',0); buf.writeUInt32LE(36+samples.length*2,4); buf.write('WAVE',8);
buf.write('fmt ',12); buf.writeUInt32LE(16,16); buf.writeUInt16LE(1,20); buf.writeUInt16LE(1,22);
buf.writeUInt32LE(SR,24); buf.writeUInt32LE(SR*2,28); buf.writeUInt16LE(2,32); buf.writeUInt16LE(16,34);
buf.write('data',36); buf.writeUInt32LE(samples.length*2,40);
let o=44; for (const s of samples){ const v=Math.max(-1,Math.min(1,s)); buf.writeInt16LE(v<0?v*32768:v*32767,o); o+=2; }
fs.writeFileSync('client/public/sounds/payment-success.wav', buf);
console.log('wrote', samples.length, 'samples');
```
Run it with `node scripts/_gen_chime.cjs`, confirm the file exists and is a valid WAV (`file client/public/sounds/payment-success.wav` should report "WAVE audio"), then delete the temp script (`rm scripts/_gen_chime.cjs`).

### Step 1 — Write the failing test `client/src/lib/__tests__/sound.test.ts`:
```ts
import { isChimeMuted, setChimeMuted } from "../sound";

describe("chime mute flag", () => {
  beforeEach(() => localStorage.clear());

  it("defaults to unmuted", () => {
    expect(isChimeMuted()).toBe(false);
  });

  it("persists a mute preference", () => {
    setChimeMuted(true);
    expect(isChimeMuted()).toBe(true);
    setChimeMuted(false);
    expect(isChimeMuted()).toBe(false);
  });
});
```
Run `npx jest client/src/lib/__tests__/sound.test.ts --verbose` → FAIL (module not found).

### Step 2 — Implement `client/src/lib/sound.ts` (note: asset path is the .wav you generated):
```ts
const MUTE_KEY = "taptpay.chime.muted";
let hasInteracted = false;

if (typeof window !== "undefined") {
  const mark = () => { hasInteracted = true; };
  window.addEventListener("pointerdown", mark, { once: true });
  window.addEventListener("keydown", mark, { once: true });
}

export function isChimeMuted(): boolean {
  try { return localStorage.getItem(MUTE_KEY) === "1"; } catch { return false; }
}

export function setChimeMuted(muted: boolean): void {
  try { localStorage.setItem(MUTE_KEY, muted ? "1" : "0"); } catch { /* ignore */ }
}

let audio: HTMLAudioElement | null = null;

/** Play the success chime. No-op when muted or before first user interaction. */
export function playPaymentChime(): void {
  if (typeof window === "undefined") return;
  if (isChimeMuted() || !hasInteracted) return;
  try {
    if (!audio) { audio = new Audio("/sounds/payment-success.wav"); audio.volume = 0.5; }
    audio.currentTime = 0;
    void audio.play().catch(() => { /* autoplay blocked — ignore */ });
  } catch { /* ignore */ }
}
```

### Step 3 — Run the test → PASS (2 tests).
### Step 4 — `npx vite build` → succeeds.
### Step 5 — Commit:
```bash
git add client/src/lib/sound.ts client/src/lib/__tests__/sound.test.ts client/public/sounds/payment-success.wav
git commit -m "feat(notifications): interaction-gated, mute-aware success chime"
```

